CREATE OR REPLACE FUNCTION public.append_canonical_trust_transaction_replay_v1(p_enterprise_id uuid, p_transaction_id uuid, p_actor_id uuid, p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  tx public.canonical_trust_transactions%rowtype;
  replay uuid;
  payload jsonb;
  item jsonb;
  artifact_replay jsonb;
begin
  select * into tx
  from public.canonical_trust_transactions
  where enterprise_id=p_enterprise_id and transaction_id=p_transaction_id
  for update;

  if tx.transaction_id is null or tx.actor_id<>p_actor_id or tx.correlation_id<>p_correlation_id then
    raise exception 'Canonical transaction scope mismatch';
  end if;
  if tx.replay_reference is not null then
    return jsonb_build_object('status','DUPLICATE','replayReference',tx.replay_reference);
  end if;

  artifact_replay:=coalesce(tx.decision_time_snapshot#>'{authorityIntegrity,replayEvents}','[]'::jsonb)
    ||coalesce(tx.decision_time_snapshot#>'{trustTwin,replayEvents}',tx.decision_time_snapshot#>'{trustForecast,replayEvents}','[]'::jsonb);

  payload:=jsonb_build_object(
    'transactionId',p_transaction_id,
    'originalDecision',tx.decision,
    'policyVersion',tx.policy_version,
    'decisionReasonCodes',to_jsonb(tx.reason_codes),
    'decisionOutcomeReview',tx.decision_outcome_review
  );

  insert into public.trust_replay_sessions(
    subject_type,subject_id,workspace_id,owner_user_id,correlation_id,
    canonical_transaction_id,replay_summary,generated_by
  ) values(
    'trust_transaction',p_transaction_id,p_enterprise_id,p_actor_id,p_correlation_id,
    p_transaction_id,payload::text
      ||case when jsonb_array_length(artifact_replay)>0
        then ' | trust intelligence events: '||jsonb_array_length(artifact_replay)::text
        else '' end,
    'canonical_trust_transaction'
  ) returning id into replay;

  for item in select value from jsonb_array_elements(artifact_replay) loop
    insert into public.canonical_trust_transaction_events(
      enterprise_id,transaction_id,event_type,actor_id,reason,evidence_references,
      authority_reference,policy_id,policy_version,correlation_id,record_digest,occurred_at
    ) values(
      p_enterprise_id,p_transaction_id,item->>'eventType',p_actor_id,
      coalesce(item->'details','{}'::jsonb)::text,
      coalesce(item->'evidenceReferences','[]'::jsonb),tx.authority_reference,
      tx.policy_id,tx.policy_version,p_correlation_id,
      encode(extensions.digest(item::text,'sha256'),'hex'),
      coalesce((item->>'occurredAt')::timestamptz,tx.requested_at)
    );
  end loop;

  update public.canonical_trust_transactions
  set replay_reference=replay,updated_at=now()
  where enterprise_id=p_enterprise_id and transaction_id=p_transaction_id;

  payload:=payload||jsonb_build_object(
    'replayReference',replay,
    'trustIntelligenceEvents',jsonb_array_length(artifact_replay)
  );
  insert into public.canonical_trust_transaction_events(
    enterprise_id,transaction_id,event_type,actor_id,reason,evidence_references,
    authority_reference,policy_id,policy_version,correlation_id,record_digest,occurred_at
  ) values(
    p_enterprise_id,p_transaction_id,'REPLAY_WRITTEN',p_actor_id,
    'Chronology appended with immutable original decision and separately retained outcome review.',
    tx.evidence_references,tx.authority_reference,tx.policy_id,tx.policy_version,
    p_correlation_id,encode(extensions.digest(payload::text,'sha256'),'hex'),now()
  );

  return jsonb_build_object('status','CREATED','replayReference',replay);
end $function$

CREATE OR REPLACE FUNCTION public.append_trust_event_v1(p_event jsonb, p_envelope_id uuid, p_correlation_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  enterprise uuid := (p_event ->> 'enterpriseId')::uuid;
  event_uuid uuid := (p_event ->> 'eventId')::uuid;
  current_head public.trust_event_chain_heads%rowtype;
  expected_sequence bigint := (p_event ->> 'sequence')::bigint;
  expected_previous text := p_event ->> 'previousHash';
  ref text;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Trusted ingestion path required';
  end if;

  if p_event ->> 'schemaVersion' <> 'trust-event-v1'
     or p_event ->> 'canonicalization' <> 'RFC8785-JCS'
     or p_event ->> 'hashAlgorithm' <> 'SHA-256'
     or (p_event ->> 'eventHash') !~ '^[a-f0-9]{64}$'
     or (p_event #>> '{subject,type}') not in (
       'HUMAN', 'AI_AGENT', 'SERVICE', 'DEVICE', 'WORKLOAD',
       'ORGANIZATION', 'UNKNOWN'
     )
     or (p_event #>> '{actor,type}') not in (
       'USER', 'AI_AGENT', 'SERVICE', 'SYSTEM', 'ADMINISTRATOR',
       'PROVIDER', 'UNKNOWN'
     )
     or (p_event #>> '{provider,protocol}') not in (
       'HMAC', 'SIGNED_JWT', 'PUBLIC_KEY_SIGNATURE',
       'CHALLENGE_RESPONSE', 'OAUTH_PROTECTED', 'MTLS',
       'UNSIGNED', 'UNSUPPORTED'
     )
     or (p_event ->> 'eventType') !~
       '^(identity|device|session|authority|workflow|runtime|security|governance|provider|system|consent)\.[a-z0-9_]+(?:\.[a-z0-9_]+)*$'
     or jsonb_typeof(p_event -> 'normalizedFacts') <> 'object'
     or jsonb_typeof(p_event -> 'reasonCodes') <> 'array'
     or jsonb_typeof(p_event -> 'evidenceReferences') <> 'array' then
    raise exception 'Invalid canonical event metadata';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(enterprise::text || ':default', 17)
  );

  insert into public.trust_event_chain_heads(
    enterprise_id,
    partition_key
  )
  values (enterprise, 'default')
  on conflict do nothing;

  select *
    into current_head
  from public.trust_event_chain_heads
  where enterprise_id = enterprise
    and partition_key = 'default'
  for update;

  if expected_sequence <> current_head.last_sequence + 1
     or coalesce(expected_previous, '') <>
       coalesce(current_head.last_event_hash, '') then
    return 'CHAIN_CONFLICT';
  end if;

  insert into public.trust_events(
    id, event_id, enterprise_id, schema_version, event_type,
    actor_type, actor_label, event_source, subject_type, subject_id,
    workflow_id, session_id, authority_id, provider_key,
    provider_protocol, provider_event_id, provider_transaction_id,
    provider_delivery_id, normalized_facts, reason_codes,
    evidence_references, occurred_at, received_at, sequence,
    previous_hash, event_hash, canonicalization, hash_algorithm,
    canonical_event, late, supersedes_event_id, metadata, created_at
  )
  values (
    event_uuid, event_uuid, enterprise, 'trust-event-v1',
    p_event ->> 'eventType', p_event #>> '{actor,type}',
    p_event #>> '{actor,id}', 'trust-event-gateway',
    p_event #>> '{subject,type}', p_event #>> '{subject,id}',
    p_event #>> '{workflow,id}', p_event #>> '{session,id}',
    p_event #>> '{authority,id}', p_event #>> '{provider,key}',
    p_event #>> '{provider,protocol}', p_event #>> '{provider,eventId}',
    p_event #>> '{provider,transactionId}',
    p_event #>> '{provider,deliveryId}', p_event -> 'normalizedFacts',
    array(select jsonb_array_elements_text(p_event -> 'reasonCodes')),
    array(select jsonb_array_elements_text(p_event -> 'evidenceReferences')),
    (p_event ->> 'occurredAt')::timestamptz,
    (p_event ->> 'receivedAt')::timestamptz, expected_sequence,
    expected_previous, p_event ->> 'eventHash',
    p_event ->> 'canonicalization', p_event ->> 'hashAlgorithm',
    p_event, coalesce((p_event #>> '{ordering,late}')::boolean, false),
    nullif(p_event #>> '{ordering,supersedesEventId}', '')::uuid,
    jsonb_build_object('canonical', true), now()
  );

  insert into public.trust_event_links(
    enterprise_id, event_id, link_type, target_id
  )
  values (
    enterprise, event_uuid, 'SUBJECT', p_event #>> '{subject,id}'
  );

  if p_event #>> '{workflow,id}' is not null then
    insert into public.trust_event_links(
      enterprise_id, event_id, link_type, target_id
    )
    values (
      enterprise, event_uuid, 'WORKFLOW', p_event #>> '{workflow,id}'
    );
  end if;

  if p_event #>> '{session,id}' is not null then
    insert into public.trust_event_links(
      enterprise_id, event_id, link_type, target_id
    )
    values (
      enterprise, event_uuid, 'SESSION', p_event #>> '{session,id}'
    );
  end if;

  if p_event #>> '{authority,id}' is not null then
    insert into public.trust_event_links(
      enterprise_id, event_id, link_type, target_id
    )
    values (
      enterprise, event_uuid, 'AUTHORITY',
      p_event #>> '{authority,id}'
    );
  end if;

  for ref in
    select jsonb_array_elements_text(p_event -> 'evidenceReferences')
  loop
    insert into public.trust_event_links(
      enterprise_id, event_id, link_type, target_id
    )
    values (enterprise, event_uuid, 'EVIDENCE', ref)
    on conflict do nothing;
  end loop;

  update public.trust_event_chain_heads
  set
    last_sequence = expected_sequence,
    last_event_id = event_uuid,
    last_event_hash = p_event ->> 'eventHash',
    updated_at = now()
  where enterprise_id = enterprise
    and partition_key = 'default';

  insert into public.trust_event_audit(
    enterprise_id, envelope_id, event_id, action, disposition,
    correlation_id, metadata
  )
  values (
    enterprise, p_envelope_id, event_uuid, 'CANONICAL_EVENT_APPENDED',
    'ACCEPTED', p_correlation_id,
    jsonb_build_object(
      'sequence', expected_sequence,
      'eventHash', p_event ->> 'eventHash'
    )
  );

  return 'APPENDED';
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_canonical_decision_outcome_review_v1(p_enterprise_id uuid, p_transaction_id uuid, p_actor_id uuid, p_review jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  tx public.canonical_trust_transactions%rowtype;
  payload jsonb;
  memory uuid;
begin
  select * into tx
  from public.canonical_trust_transactions
  where enterprise_id=p_enterprise_id and transaction_id=p_transaction_id
  for update;

  if tx.transaction_id is null then
    raise exception 'Cross-tenant transaction reference rejected';
  end if;
  if p_review->>'originalDecision'<>tx.decision
    or p_review->>'policyVersion'<>tx.policy_version
    or coalesce(p_review->'decisionReasonCodes','[]'::jsonb)<>to_jsonb(tx.reason_codes)
  then
    raise exception 'Cross-tenant or mismatched decision reference rejected';
  end if;
  if tx.decision_outcome_review is not null then
    if tx.decision_outcome_review=p_review then
      return jsonb_build_object('status','DUPLICATE','transactionId',p_transaction_id);
    end if;
    raise exception 'Canonical decision-outcome review is already attached';
  end if;

  update public.canonical_trust_transactions
  set decision_outcome_review=p_review,updated_at=now()
  where enterprise_id=p_enterprise_id and transaction_id=p_transaction_id;

  payload:=jsonb_build_object(
    'transactionId',p_transaction_id,
    'decisionId',tx.decision_id,
    'originalDecision',tx.decision,
    'decisionOutcomeReview',p_review
  );
  insert into public.canonical_trust_transaction_events(
    enterprise_id,transaction_id,event_type,actor_id,reason,evidence_references,
    authority_reference,policy_id,policy_version,correlation_id,record_digest,occurred_at
  ) values(
    p_enterprise_id,p_transaction_id,'DECISION_OUTCOME_REVIEW_ATTACHED',p_actor_id,
    'Later outcome evidence and adjudication attached without mutating the original decision.',
    tx.evidence_references,tx.authority_reference,tx.policy_id,tx.policy_version,
    tx.correlation_id,encode(digest(payload::text,'sha256'),'hex'),now()
  );

  insert into public.trust_memory_index(
    enterprise_id,subject_id,domain_key,memory_type,source_id,occurred_at,summary,correlation_id
  ) values(
    p_enterprise_id,tx.subject_id,'GOVERNANCE','DECISION_OUTCOME_REVIEW',p_transaction_id::text,
    now(),jsonb_build_object(
      'originalDecision',tx.decision,
      'action',jsonb_build_object(
        'type',tx.action_type,
        'purpose',tx.action_purpose,
        'resource',tx.action_resource,
        'environment',tx.action_environment
      ),
      'observedOutcomes',jsonb_build_object(
        'providerOutcome',p_review->'providerOutcome',
        'runtimeOutcome',p_review->'runtimeOutcome',
        'destinationOutcome',p_review->'destinationOutcome'
      ),
      'laterAdjudication',jsonb_build_object(
        'adjudicatedOutcome',p_review->'adjudicatedOutcome',
        'humanOverride',p_review->'humanOverride'
      ),
      'evaluationStatus',p_review->'evaluationStatus',
      'decisionOutcomeReview',p_review
    ),tx.correlation_id
  ) returning memory_id into memory;

  insert into public.trust_architecture_audit_log(
    enterprise_id,action,actor_reference,target_type,target_id,correlation_id,metadata
  ) values(
    p_enterprise_id,'DECISION_OUTCOME_REVIEW_ATTACHED','user:'||p_actor_id::text,
    'CANONICAL_TRUST_TRANSACTION',p_transaction_id::text,tx.correlation_id,payload
  );

  return jsonb_build_object(
    'status','CREATED',
    'transactionId',p_transaction_id,
    'decisionId',tx.decision_id,
    'trustMemoryReference',memory
  );
end $function$

CREATE OR REPLACE FUNCTION public.extend_canonical_trust_transaction_graph_v1(p_enterprise_id uuid, p_transaction_id uuid, p_actor_id uuid, p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  tx public.canonical_trust_transactions%rowtype;
  subject_node uuid; tx_node uuid; decision_node uuid; authority_node uuid; policy_node uuid; evidence_node uuid;
  from_node uuid; to_node uuid; item jsonb; edge jsonb; projection jsonb; payload jsonb;
  authority_projection jsonb; forecast_projection jsonb; twin_projection jsonb;
begin
  select * into tx from public.canonical_trust_transactions where enterprise_id=p_enterprise_id and transaction_id=p_transaction_id for update;
  if tx.transaction_id is null or tx.actor_id<>p_actor_id or tx.correlation_id<>p_correlation_id then raise exception 'Canonical transaction scope mismatch'; end if;
  if tx.evidence_graph_reference is not null then return jsonb_build_object('status','DUPLICATE','evidenceGraphReference',tx.evidence_graph_reference); end if;
  insert into public.evidence_graph_nodes(enterprise_id,node_type,external_id,domain_key,label,metadata,correlation_id) values
    (p_enterprise_id,'SUBJECT',tx.subject_id,'IDENTITY','Trust Object',jsonb_build_object('subjectType',tx.subject_type),p_correlation_id),
    (p_enterprise_id,'TRUST_TRANSACTION',tx.transaction_id::text,'WORKFLOW',tx.action_type,jsonb_build_object('decision',tx.decision,'requestDigest',tx.request_digest),p_correlation_id),
    (p_enterprise_id,'DECISION',tx.decision_id::text,'GOVERNANCE',tx.decision,jsonb_build_object('trustState',tx.trust_state),p_correlation_id),
    (p_enterprise_id,'AUTHORITY',tx.authority_reference,'AUTHORITY','Authority lineage',jsonb_build_object('reference',tx.authority_reference),p_correlation_id),
    (p_enterprise_id,'POLICY',tx.policy_id||':'||tx.policy_version,'GOVERNANCE','Policy version',jsonb_build_object('policyHash',tx.policy_hash),p_correlation_id)
  on conflict do nothing;
  select node_id into subject_node from public.evidence_graph_nodes where enterprise_id=p_enterprise_id and node_type='SUBJECT' and external_id=tx.subject_id;
  select node_id into tx_node from public.evidence_graph_nodes where enterprise_id=p_enterprise_id and node_type='TRUST_TRANSACTION' and external_id=tx.transaction_id::text;
  select node_id into decision_node from public.evidence_graph_nodes where enterprise_id=p_enterprise_id and node_type='DECISION' and external_id=tx.decision_id::text;
  select node_id into authority_node from public.evidence_graph_nodes where enterprise_id=p_enterprise_id and node_type='AUTHORITY' and external_id=tx.authority_reference;
  select node_id into policy_node from public.evidence_graph_nodes where enterprise_id=p_enterprise_id and node_type='POLICY' and external_id=tx.policy_id||':'||tx.policy_version;
  insert into public.evidence_graph_edges(enterprise_id,from_node_id,to_node_id,edge_type,correlation_id) values
    (p_enterprise_id,subject_node,tx_node,'PARTICIPATED_IN',p_correlation_id),
    (p_enterprise_id,tx_node,authority_node,'AUTHORIZED_BY',p_correlation_id),
    (p_enterprise_id,policy_node,decision_node,'APPLIES_TO',p_correlation_id),
    (p_enterprise_id,decision_node,tx_node,'RESULTED_IN',p_correlation_id)
  on conflict do nothing;
  for item in select value from jsonb_array_elements(tx.evidence_references) loop
    insert into public.evidence_graph_nodes(enterprise_id,node_type,external_id,domain_key,label,metadata,correlation_id) values(p_enterprise_id,'EVIDENCE_REFERENCE',item->>'reference','IDENTITY',item->>'providerId',jsonb_build_object('providerEventId',item->>'providerEventId','sourceDigest',item->>'sourceDigest'),p_correlation_id) on conflict do nothing;
    select node_id into evidence_node from public.evidence_graph_nodes where enterprise_id=p_enterprise_id and node_type='EVIDENCE_REFERENCE' and external_id=item->>'reference';
    insert into public.evidence_graph_edges(enterprise_id,from_node_id,to_node_id,edge_type,correlation_id) values(p_enterprise_id,evidence_node,decision_node,'SUPPORTED',p_correlation_id) on conflict do nothing;
  end loop;
  authority_projection:=coalesce(tx.decision_time_snapshot#>'{authorityIntegrity,graphProjection}','{}'::jsonb);
  forecast_projection:=coalesce(tx.decision_time_snapshot#>'{trustForecast,graphProjection}','{}'::jsonb);
  twin_projection:=coalesce(tx.decision_time_snapshot#>'{trustTwin,graphProjection}','{}'::jsonb);
  for projection in select value from jsonb_array_elements(jsonb_build_array(authority_projection,forecast_projection,twin_projection)) loop
    for item in select value from jsonb_array_elements(coalesce(projection->'nodes','[]'::jsonb)) loop
      if nullif(item->>'nodeType','') is not null and nullif(item->>'externalId','') is not null then
        insert into public.evidence_graph_nodes(enterprise_id,node_type,external_id,domain_key,label,metadata,correlation_id)
        values(p_enterprise_id,item->>'nodeType',item->>'externalId',coalesce(nullif(item->>'domainKey',''),'GOVERNANCE'),item->>'label',coalesce(item->'metadata','{}'::jsonb)||jsonb_build_object('canonicalTransactionId',p_transaction_id),p_correlation_id)
        on conflict do nothing;
      end if;
    end loop;
    for edge in select value from jsonb_array_elements(coalesce(projection->'edges','[]'::jsonb)) loop
      select node_id into from_node from public.evidence_graph_nodes where enterprise_id=p_enterprise_id and node_type=edge->>'fromNodeType' and external_id=edge->>'fromExternalId';
      select node_id into to_node from public.evidence_graph_nodes where enterprise_id=p_enterprise_id and node_type=edge->>'toNodeType' and external_id=edge->>'toExternalId';
      if from_node is not null and to_node is not null then
        insert into public.evidence_graph_edges(enterprise_id,from_node_id,to_node_id,edge_type,correlation_id)
        values(p_enterprise_id,from_node,to_node,edge->>'edgeType',p_correlation_id) on conflict do nothing;
      end if;
    end loop;
  end loop;
  update public.canonical_trust_transactions set evidence_graph_reference=tx_node,updated_at=now() where enterprise_id=p_enterprise_id and transaction_id=p_transaction_id;
  payload:=jsonb_build_object('transactionId',p_transaction_id,'evidenceGraphReference',tx_node,'authorityIntegrityNodes',jsonb_array_length(coalesce(authority_projection->'nodes','[]'::jsonb)),'trustForecastNodes',jsonb_array_length(coalesce(forecast_projection->'nodes','[]'::jsonb)),'trustTwinNodes',jsonb_array_length(coalesce(twin_projection->'nodes','[]'::jsonb)));
  insert into public.canonical_trust_transaction_events(enterprise_id,transaction_id,event_type,actor_id,reason,evidence_references,authority_reference,policy_id,policy_version,correlation_id,record_digest,occurred_at)
  values(p_enterprise_id,p_transaction_id,'EVIDENCE_GRAPH_LINKED',p_actor_id,'Canonical authority-integrity, Trust Twin, pressure, budget, and Trust Forecast relationships linked.',tx.evidence_references,tx.authority_reference,tx.policy_id,tx.policy_version,p_correlation_id,encode(extensions.digest(payload::text,'sha256'),'hex'),now());
  return jsonb_build_object('status','CREATED','evidenceGraphReference',tx_node);
end $function$

CREATE OR REPLACE FUNCTION public.persist_canonical_trust_transaction_decision_v1(p_transaction jsonb, p_decision jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  enterprise uuid:=(p_transaction->>'enterpriseId')::uuid;
  transaction uuid:=(p_transaction->>'transactionId')::uuid;
  actor uuid:=(p_transaction->>'actorId')::uuid;
  correlation uuid:=(p_transaction->>'correlationId')::uuid;
  existing public.canonical_trust_transactions%rowtype;
  event_payload jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(enterprise::text||':'||(p_transaction->>'idempotencyKey'),89));
  select * into existing from public.canonical_trust_transactions where enterprise_id=enterprise and idempotency_key=p_transaction->>'idempotencyKey';
  if found then
    if existing.actor_id<>actor or existing.subject_type<>p_transaction->>'subjectType' or existing.subject_id<>p_transaction->>'subjectId'
      or existing.action_type<>p_transaction->>'actionType' or existing.action_purpose<>p_transaction->>'actionPurpose'
      or existing.action_resource<>p_transaction->>'actionResource' or existing.action_environment<>p_transaction->>'actionEnvironment'
      or existing.request_digest<>p_transaction->>'requestDigest'
    then raise exception 'Canonical transaction idempotency conflict'; end if;
    return jsonb_build_object('status','DUPLICATE','transactionId',existing.transaction_id,'decisionId',existing.decision_id);
  end if;
  if nullif(p_transaction->>'previousTransactionId','') is not null and not exists(
    select 1 from public.canonical_trust_transactions where enterprise_id=enterprise and transaction_id=(p_transaction->>'previousTransactionId')::uuid
  ) then raise exception 'Previous transaction tenant mismatch'; end if;
  insert into public.canonical_trust_transactions(
    transaction_id,enterprise_id,actor_id,actor_type,operational_entity_id,accountable_owner_id,entity_type,entity_lifecycle_state,
    subject_type,subject_id,workflow_id,action_type,action_purpose,action_resource,action_environment,request_digest,idempotency_key,
    correlation_id,requested_at,decision,trust_state,decision_id,authority_reference,authority_lineage_references,policy_id,policy_version,
    policy_hash,evidence_references,evidence_digest,evidence_complete,evidence_fresh,reason_codes,previous_transaction_id,changed_conditions,
    material_change,responsibility_lineage,evidence_independence,decision_time_snapshot,continuity_signals,provider_neutral_evidence,
    deployment_gate,execution_continuity,decision_outcome_review
  ) values (
    transaction,enterprise,actor,p_transaction->>'actorType',p_transaction->>'operationalEntityId',p_transaction->>'accountableOwnerId',p_transaction->>'entityType',p_transaction->>'entityLifecycleState',
    p_transaction->>'subjectType',p_transaction->>'subjectId',p_transaction->>'workflowId',p_transaction->>'actionType',p_transaction->>'actionPurpose',
    p_transaction->>'actionResource',p_transaction->>'actionEnvironment',p_transaction->>'requestDigest',p_transaction->>'idempotencyKey',correlation,
    (p_transaction->>'requestedAt')::timestamptz,p_transaction->>'decision',p_transaction->>'trustState',(p_transaction->>'decisionId')::uuid,
    p_transaction->>'authorityReference',coalesce(p_transaction->'authorityLineageReferences','[]'::jsonb),p_transaction->>'policyId',
    p_transaction->>'policyVersion',p_transaction->>'policyHash',coalesce(p_transaction->'evidenceReferences','[]'::jsonb),p_transaction->>'evidenceDigest',
    (p_transaction->>'evidenceComplete')::boolean,(p_transaction->>'evidenceFresh')::boolean,array(select jsonb_array_elements_text(coalesce(p_transaction->'reasonCodes','[]'::jsonb))),
